-- T06 immutable evidence/source facts, current review ownership and explicit settled cash.
grant create on schema api,app_private,finance_private to git_tutor_commands;
create table app_private.files(
 id uuid primary key default gen_random_uuid(),uploader_account_id uuid not null references app_private.accounts(id),learner_id uuid references app_private.learners(id),charge_id uuid references finance_private.charges(id),
 parent_type text not null,parent_id uuid,purpose text not null,object_key text not null unique,object_version text not null,
 checksum_sha256 text not null check(checksum_sha256~'^[a-f0-9]{64}$'),detected_mime text not null,byte_size bigint not null check(byte_size between 1 and 26214400),
 scan_state text not null check(scan_state in('pending','clean','quarantined')),source_provenance text not null,created_at timestamptz not null default now()
);
create table finance_private.receiving_accounts(id uuid primary key default gen_random_uuid(),channel text not null check(channel in('instapay','vodafone_cash')),current_version_id uuid,enabled boolean not null default false,created_by uuid not null references app_private.accounts(id),version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table finance_private.receiving_account_versions(id uuid primary key default gen_random_uuid(),receiving_account_id uuid not null references finance_private.receiving_accounts(id),version_number integer not null check(version_number>0),collection_identifier text not null,display_instructions text not null,ownership_evidence_file_id uuid not null references app_private.files(id),approved_by uuid references app_private.accounts(id),approved_at timestamptz,instructions_version integer not null check(instructions_version>0),created_at timestamptz not null default now(),unique(receiving_account_id,version_number),unique(id,receiving_account_id));
alter table finance_private.receiving_accounts add foreign key(current_version_id,id) references finance_private.receiving_account_versions(id,receiving_account_id) deferrable initially deferred;
create table finance_private.incoming_transfers(
 id uuid primary key default gen_random_uuid(),receiving_account_id uuid not null references finance_private.receiving_accounts(id),receiving_account_version_id uuid not null,
 channel text not null check(channel in('instapay','vodafone_cash')),external_id text not null check(length(btrim(external_id)) between 1 and 200),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),currency text not null check(currency='EGP'),observed_at timestamptz not null,
 statement_evidence_file_id uuid not null references app_private.files(id),state text not null default 'pending' check(state in('pending','settled','reversed')),current_payer_binding_id uuid,created_by uuid references app_private.accounts(id),version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(receiving_account_id,channel,external_id),foreign key(receiving_account_version_id,receiving_account_id) references finance_private.receiving_account_versions(id,receiving_account_id)
);
create table finance_private.transfer_settlements(id uuid primary key default gen_random_uuid(),transfer_id uuid not null unique references finance_private.incoming_transfers(id),statement_evidence_id uuid not null references app_private.files(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),currency text not null check(currency='EGP'),settled_at timestamptz not null,verified_by uuid not null references app_private.accounts(id),verification_note text not null,ledger_transaction_id uuid not null references finance_private.ledger_transactions(id),command_id uuid not null,recorded_at timestamptz not null default now());
create table finance_private.transfer_payer_bindings(id uuid primary key default gen_random_uuid(),transfer_id uuid not null references finance_private.incoming_transfers(id),payer_account_id uuid not null references app_private.accounts(id),evidence_file_id uuid not null references app_private.files(id),verified_by uuid not null references app_private.accounts(id),reason text not null,supersedes_id uuid references finance_private.transfer_payer_bindings(id),command_id uuid not null,recorded_at timestamptz not null default now(),unique(id,transfer_id));
alter table finance_private.incoming_transfers add foreign key(current_payer_binding_id,id) references finance_private.transfer_payer_bindings(id,transfer_id) deferrable initially deferred;
create table app_private.receipts(id uuid primary key default gen_random_uuid(),learner_id uuid not null references app_private.learners(id),charge_id uuid not null references finance_private.charges(id),enrollment_id uuid references app_private.enrollments(id),submitted_by uuid not null references app_private.accounts(id),current_evidence_version integer not null default 1,current_evidence_id uuid,version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.receipt_evidence(
 id uuid primary key default gen_random_uuid(),receipt_id uuid not null references app_private.receipts(id),evidence_version integer not null check(evidence_version>0),learner_id uuid not null references app_private.learners(id),charge_id uuid not null references finance_private.charges(id),enrollment_id uuid references app_private.enrollments(id),uploader_account_id uuid not null references app_private.accounts(id),submission_authority jsonb not null,file_id uuid not null references app_private.files(id),checksum_sha256 text not null,
 receiving_account_version_id uuid not null references finance_private.receiving_account_versions(id),channel text not null check(channel in('instapay','vodafone_cash')),reported_amount_minor bigint not null check(reported_amount_minor between 1 and 9007199254740991),currency text not null check(currency='EGP'),reference text not null,transferred_at timestamptz,state text not null check(state in('uploaded','quarantined','ready_for_review','superseded','rejected')),submitted_at timestamptz not null default now(),unique(receipt_id,evidence_version),unique(id,receipt_id)
);
alter table app_private.receipts add foreign key(current_evidence_id,id) references app_private.receipt_evidence(id,receipt_id) deferrable initially deferred;
create table app_private.review_cases(id uuid primary key default gen_random_uuid(),receipt_id uuid not null unique references app_private.receipts(id),current_evidence_version integer not null,state text not null default 'unassigned' check(state in('waiting_for_evidence','unassigned','claimed','needs_information','escalated','resolved')),owner_id uuid references app_private.accounts(id),claim_expires_at timestamptz,resolved_at timestamptz,version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.review_case_events(id uuid primary key default gen_random_uuid(),case_id uuid not null references app_private.review_cases(id),event_type text not null,evidence_version integer not null,owner_id uuid references app_private.accounts(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null,reason text,details jsonb not null default '{}',recorded_at timestamptz not null default now());
create table app_private.payment_allocation_plans(id uuid primary key default gen_random_uuid(),receipt_id uuid not null references app_private.receipts(id),evidence_version integer not null,author_account_id uuid not null references app_private.accounts(id),plan_version integer not null,plan_hash text not null check(plan_hash~'^[a-f0-9]{64}$'),state text not null default 'active' check(state in('active','superseded')),command_id uuid not null,created_at timestamptz not null default now(),unique(receipt_id,plan_version));
create table app_private.payment_plan_targets(id uuid primary key default gen_random_uuid(),plan_id uuid not null references app_private.payment_allocation_plans(id),charge_id uuid not null references finance_private.charges(id),learner_id uuid not null references app_private.learners(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),conditional_amendment_id uuid references app_private.group_amendments(id),receipt_evidence_id uuid not null references app_private.receipt_evidence(id),receipt_id uuid not null references app_private.receipts(id),evidence_version integer not null,file_id uuid not null references app_private.files(id),checksum_sha256 text not null,author_account_id uuid not null references app_private.accounts(id),authority_ref jsonb not null,unique(plan_id,charge_id));
create table app_private.transfer_payment_plan_links(id uuid primary key default gen_random_uuid(),case_id uuid not null references app_private.review_cases(id),transfer_id uuid not null references finance_private.incoming_transfers(id),payer_binding_id uuid not null references finance_private.transfer_payer_bindings(id),payment_plan_id uuid not null references app_private.payment_allocation_plans(id),customer_plan_hash text not null,source_intent_hash text not null,expires_at timestamptz not null,state text not null default 'awaiting_payer_acceptance' check(state in('awaiting_payer_acceptance','accepted','invalidated')),created_by uuid not null references app_private.accounts(id),version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.transfer_payment_plan_acceptances(id uuid primary key default gen_random_uuid(),plan_link_id uuid not null unique references app_private.transfer_payment_plan_links(id),payer_account_id uuid not null references app_private.accounts(id),auth_session_id uuid not null,source_intent_hash text not null,accepted_at timestamptz not null default now(),command_id uuid not null);
create table finance_private.payment_allocations(id uuid primary key default gen_random_uuid(),transfer_id uuid not null references finance_private.incoming_transfers(id),charge_id uuid not null references finance_private.charges(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),currency text not null check(currency='EGP'),payer_binding_id uuid not null references finance_private.transfer_payer_bindings(id),review_case_id uuid not null references app_private.review_cases(id),receipt_id uuid not null references app_private.receipts(id),evidence_version integer not null,payment_plan_id uuid references app_private.payment_allocation_plans(id),plan_target_id uuid references app_private.payment_plan_targets(id),payer_intent_acceptance_id uuid references app_private.transfer_payment_plan_acceptances(id),ledger_transaction_id uuid references finance_private.ledger_transactions(id) deferrable initially deferred,actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null,source_line_key text not null,effective_at timestamptz not null,recorded_at timestamptz not null default now(),unique(command_id,source_line_key));
create table finance_private.allocation_reversals(id uuid primary key default gen_random_uuid(),allocation_id uuid not null references finance_private.payment_allocations(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),reason text not null,reversal_kind text not null,domain_source_id uuid not null,replacement_allocation_id uuid references finance_private.payment_allocations(id) deferrable initially deferred,ledger_transaction_id uuid references finance_private.ledger_transactions(id) deferrable initially deferred,actor_account_id uuid references app_private.accounts(id),command_id uuid not null,source_line_key text not null,effective_at timestamptz not null,recorded_at timestamptz not null default now(),unique(command_id,source_line_key));
create table finance_private.customer_credit_lots(id uuid primary key default gen_random_uuid(),transfer_id uuid not null references finance_private.incoming_transfers(id),payer_binding_id uuid not null references finance_private.transfer_payer_bindings(id),payer_account_id uuid not null references app_private.accounts(id),origin_kind text not null check(origin_kind in('settlement','allocation_release','refund_reversal')),source_allocation_id uuid references finance_private.payment_allocations(id),source_adjustment_id uuid references finance_private.charge_adjustments(id) deferrable initially deferred,source_refund_reversal_id uuid,original_minor bigint not null check(original_minor between 1 and 9007199254740991),currency text not null check(currency='EGP'),command_id uuid not null,source_line_key text not null,created_at timestamptz not null default now(),unique(command_id,source_line_key));
create unique index credit_settlement_once on finance_private.customer_credit_lots(transfer_id) where origin_kind='settlement';
create table finance_private.credit_lot_accounts(credit_lot_id uuid primary key references finance_private.customer_credit_lots(id),version integer not null default 1 check(version>0),updated_at timestamptz not null default now());
create table finance_private.credit_reservations(id uuid primary key default gen_random_uuid(),credit_lot_id uuid not null references finance_private.customer_credit_lots(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),purpose text not null check(purpose in('allocation','refund','package_grant','amendment')),source_id uuid not null,state text not null default 'reserved' check(state in('reserved','consumed','released')),expires_at timestamptz,version integer not null default 1 check(version>0),command_id uuid not null,source_line_key text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(command_id,source_line_key));
create table finance_private.credit_applications(id uuid primary key default gen_random_uuid(),credit_reservation_id uuid not null unique references finance_private.credit_reservations(id),application_type text not null,application_id uuid not null,amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),command_id uuid not null,created_at timestamptz not null default now());
create table finance_private.transfer_reversals(id uuid primary key default gen_random_uuid(),transfer_id uuid not null references finance_private.incoming_transfers(id),receiving_account_id uuid not null references finance_private.receiving_accounts(id),channel text not null,external_reversal_id text not null,amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),evidence_file_id uuid not null references app_private.files(id),ledger_transaction_id uuid not null references finance_private.ledger_transactions(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null,effective_at timestamptz not null,recorded_at timestamptz not null default now(),unique(receiving_account_id,channel,external_reversal_id));
create table finance_private.transfer_reversal_resolutions(id uuid primary key default gen_random_uuid(),reversal_id uuid not null references finance_private.transfer_reversals(id),allocations jsonb not null,unapplied_minor bigint not null check(unapplied_minor between 0 and 9007199254740991),reason text not null,actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null,recorded_at timestamptz not null default now());
create table app_private.reconciliation_exceptions(id uuid primary key default gen_random_uuid(),source_type text not null,source_id uuid not null,kind text not null check(length(kind) between 1 and 100),owner_id uuid references app_private.accounts(id),state text not null default 'open' check(state in('open','resolved')),signed_exposure_minor bigint not null check(signed_exposure_minor between -9007199254740991 and 9007199254740991),currency text not null default 'EGP' check(currency='EGP'),reason text not null,resolution_id uuid,version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.credit_conversion_intents(id uuid primary key default gen_random_uuid(),source_credit_id uuid not null references finance_private.customer_credit_lots(id),payer_binding_id uuid not null references finance_private.transfer_payer_bindings(id),payer_account_id uuid not null references app_private.accounts(id),learner_id uuid not null references app_private.learners(id),package_purchase_id uuid not null references app_private.package_purchases(id),contract_terms_hash text not null,credit_quanta bigint not null check(credit_quanta between 1 and 9007199254740991),carrying_value_minor bigint not null check(carrying_value_minor between 1 and 9007199254740991),grant_policy_version_id uuid not null references app_private.package_grant_policy_versions(id),expires_at timestamptz,intent_hash text not null,accepted_at timestamptz not null default now(),state text not null default 'authorized' check(state in('authorized','consumed','expired','invalidated')),consumed_grant_id uuid references app_private.package_lots(id),version integer not null default 1 check(version>0),command_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index receipt_by_learner on app_private.receipts(learner_id,created_at desc,id desc);
create index review_case_work on app_private.review_cases(state,updated_at,id);
create index allocation_source on finance_private.payment_allocations(transfer_id,charge_id);
create index allocation_charge on finance_private.payment_allocations(charge_id,id);
create index credit_owner on finance_private.customer_credit_lots(payer_account_id,created_at,id);
create index credit_reservation_source on finance_private.credit_reservations(credit_lot_id,state);
create index transfer_owner on finance_private.transfer_payer_bindings(payer_account_id,transfer_id);
alter table finance_private.ledger_lines add foreign key(transfer_id) references finance_private.incoming_transfers(id) deferrable initially deferred,add foreign key(allocation_id) references finance_private.payment_allocations(id) deferrable initially deferred,add foreign key(credit_lot_id) references finance_private.customer_credit_lots(id) deferrable initially deferred,add foreign key(receiving_account_id) references finance_private.receiving_accounts(id);

create function app_private.payment_current_staff(p_actor uuid) returns void language plpgsql security definer set search_path='' as $$
begin if not app_private.has_role(p_actor,'admin') and not app_private.has_role(p_actor,'customer_service') then raise exception 'FORBIDDEN' using errcode='42501';end if;end $$;
create function app_private.payment_verified_account(p_account uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from app_private.accounts a cross join lateral app_private.auth_account(a.id) u where a.id=p_account and a.active and u.email_confirmed_at is not null and not u.is_anonymous and u.deleted_at is null and(u.banned_until is null or u.banned_until<=now()))
$$;
create function app_private.payment_assert_file(p_file uuid,p_purpose text,p_parent_type text,p_parent_id uuid,p_uploader uuid default null) returns app_private.files language plpgsql stable security definer set search_path='' as $$
declare f app_private.files%rowtype;begin
 select * into f from app_private.files where id=p_file;
 if f.id is null or f.purpose is distinct from p_purpose or f.parent_type is distinct from p_parent_type or f.parent_id is distinct from p_parent_id or(p_uploader is not null and f.uploader_account_id<>p_uploader) then raise exception 'EVIDENCE_REQUIRED';end if;
 if f.scan_state<>'clean' then raise exception 'FILE_REJECTED';end if;
 if f.source_provenance like 'synthetic%' and not exists(select 1 from app_private.environment_metadata where environment in('test','development') and fixture_marker is not null) then raise exception 'EVIDENCE_REQUIRED';end if;
 if p_purpose='payment_receipt' then if f.byte_size>5242880 or f.detected_mime not in('application/pdf','image/png','image/jpeg','image/webp') then raise exception 'FILE_REJECTED';end if;
 elsif f.byte_size>26214400 or f.detected_mime not in('application/pdf','text/csv','image/png','image/jpeg','image/webp') then raise exception 'FILE_REJECTED';end if;
 return f;
end $$;

create function app_private.payment_source_command(p_name text,p_input jsonb,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
<<payment_source_command>>
declare actor uuid:=app_private.require_actor();context jsonb;expected integer:=(p_input->>'expected_version')::int;account finance_private.receiving_accounts%rowtype;account_version finance_private.receiving_account_versions%rowtype;t finance_private.incoming_transfers%rowtype;c finance_private.charges%rowtype;r app_private.receipts%rowtype;e app_private.receipt_evidence%rowtype;review app_private.review_cases%rowtype;file app_private.files%rowtype;resource uuid;version integer;result jsonb:='{}';amount bigint;at_time timestamptz;entry uuid;binding uuid;posting uuid;owner uuid;state text;begin
 if p_name in('create_receiving_account','approve_receiving_account','assign_review_case') then perform app_private.require_role(actor,'admin');
 elsif p_name in('record_manual_transfer','verify_transfer_settlement','bind_transfer_payer','claim_review_case','renew_review_claim','release_review_case','decide_review_case') then perform app_private.payment_current_staff(actor);
 elsif p_name='submit_receipt' then select * into c from finance_private.charges where id=(p_input->>'charge_id')::uuid;if c.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;perform app_private.package_assert_scope(actor,c.learner_id,'payments');
 elsif p_name='replace_receipt' then select * into r from app_private.receipts where id=(p_input->>'receipt_id')::uuid;if r.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;perform app_private.package_assert_scope(actor,r.learner_id,'payments');
 else raise exception 'VALIDATION_ERROR';end if;
 if p_name in('renew_review_claim','release_review_case','decide_review_case') then
  select * into review from app_private.review_cases where id=(p_input->>'case_id')::uuid;if review.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;
  if review.owner_id is distinct from actor and not(p_name='release_review_case' and app_private.has_role(actor,'admin')) then raise exception 'OWNER_REQUIRED';end if;
 end if;
 context:=app_private.booking_begin(actor,p_name,p_input,p_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 if p_input?'reason' and(p_input->>'reason' is null or length(btrim(p_input->>'reason')) not between 1 and 2000) then raise exception 'VALIDATION_ERROR';end if;
 if p_name='create_receiving_account' then
  if p_input->>'channel' is null or p_input->>'channel' not in('instapay','vodafone_cash') or p_input->>'collection_identifier' is null or length(btrim(p_input->>'collection_identifier')) not between 1 and 200 or p_input->>'display_instructions' is null or length(btrim(p_input->>'display_instructions')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
  file:=app_private.payment_assert_file((p_input->>'ownership_evidence_file_id')::uuid,'receiving_ownership','receiving_account',null,actor);
  insert into finance_private.receiving_accounts(channel,created_by) values(p_input->>'channel',actor) returning * into account;
  insert into finance_private.receiving_account_versions(receiving_account_id,version_number,collection_identifier,display_instructions,ownership_evidence_file_id,instructions_version) values(account.id,1,btrim(p_input->>'collection_identifier'),btrim(p_input->>'display_instructions'),file.id,1);
  resource:=account.id;version:=account.version;result:=jsonb_build_object('receiving_account_id',account.id);perform set_config('response.status','201',true);
 elsif p_name='approve_receiving_account' then
  select * into account from finance_private.receiving_accounts where id=(p_input->>'receiving_account_id')::uuid for update;if account.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;if expected is distinct from account.version then raise exception 'VERSION_CONFLICT';end if;
  if jsonb_typeof(p_input->'enabled') is distinct from 'boolean' or p_input->>'verification_note' is null or length(btrim(p_input->>'verification_note')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
  select * into account_version from finance_private.receiving_account_versions where receiving_account_id=account.id order by version_number desc limit 1;
  perform app_private.payment_assert_file(account_version.ownership_evidence_file_id,'receiving_ownership','receiving_account',null);
  update finance_private.receiving_account_versions set approved_by=coalesce(approved_by,actor),approved_at=coalesce(approved_at,now()) where id=account_version.id returning * into account_version;
  update finance_private.receiving_accounts set current_version_id=account_version.id,enabled=(p_input->>'enabled')::boolean,version=receiving_accounts.version+1,updated_at=now() where id=account.id returning * into account;
  resource:=account.id;version:=account.version;result:=jsonb_build_object('verified_at',account_version.approved_at,'instructions_version',account_version.instructions_version);
 elsif p_name='record_manual_transfer' then
  select * into account from finance_private.receiving_accounts where id=(p_input->>'receiving_account_id')::uuid;if account.id is null or not account.enabled or account.current_version_id is null then raise exception 'DESTINATION_UNVERIFIED';end if;
  amount:=app_private.package_safe_integer(p_input->'amount_minor',1);at_time:=(p_input->>'observed_at')::timestamptz;
  if p_input->>'channel' is distinct from account.channel or p_input->>'currency' is distinct from 'EGP' or p_input->>'external_id' is null or length(btrim(p_input->>'external_id')) not between 1 and 200 then raise exception 'VALIDATION_ERROR';end if;
  if at_time is null or not isfinite(at_time) or at_time<timestamptz '0001-01-01 00:00:00+00' or at_time>now() then raise exception 'INVALID_TIME';end if;
  file:=app_private.payment_assert_file((p_input->>'statement_evidence_file_id')::uuid,'statement','receiving_account',account.id);
  if exists(select 1 from finance_private.incoming_transfers where receiving_account_id=account.id and channel=account.channel and external_id=btrim(p_input->>'external_id')) then raise exception 'DUPLICATE_TRANSFER';end if;
  insert into finance_private.incoming_transfers(receiving_account_id,receiving_account_version_id,channel,external_id,amount_minor,currency,observed_at,statement_evidence_file_id,created_by) values(account.id,account.current_version_id,account.channel,btrim(p_input->>'external_id'),amount,'EGP',at_time,file.id,actor) returning * into t;
  resource:=t.id;version:=t.version;result:=jsonb_build_object('transfer_id',t.id,'state',t.state);perform set_config('response.status','201',true);
 elsif p_name in('verify_transfer_settlement','bind_transfer_payer') then
  select * into t from finance_private.incoming_transfers where id=(p_input->>'transfer_id')::uuid for update;if t.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;if expected is distinct from t.version then raise exception 'VERSION_CONFLICT';end if;
  if p_name='verify_transfer_settlement' then
   if t.state<>'pending' then raise exception 'STATE_CONFLICT';end if;
   amount:=app_private.package_safe_integer(p_input->'amount_minor',1);at_time:=(p_input->>'settled_at')::timestamptz;
   if p_input->>'external_id' is distinct from t.external_id or amount<>t.amount_minor or p_input->>'currency' is distinct from t.currency or p_input->>'verification_note' is null or length(btrim(p_input->>'verification_note')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
   if at_time is null or not isfinite(at_time) or at_time<timestamptz '0001-01-01 00:00:00+00' or at_time>now() then raise exception 'INVALID_TIME';end if;
   file:=app_private.payment_assert_file((p_input->>'statement_evidence_id')::uuid,'statement','receiving_account',t.receiving_account_id);
   posting:=finance_private.finance_post_settlement(t.id,file.id,context||jsonb_build_object('effective_at',at_time));
   insert into finance_private.transfer_settlements(transfer_id,statement_evidence_id,amount_minor,currency,settled_at,verified_by,verification_note,ledger_transaction_id,command_id) values(t.id,file.id,t.amount_minor,t.currency,at_time,actor,p_input->>'verification_note',posting,(context->>'command_id')::uuid);
   update finance_private.incoming_transfers set state='settled',version=incoming_transfers.version+1,updated_at=now() where id=t.id returning * into t;
   perform finance_private.finance_ensure_owned_credit(t.id,context);result:=jsonb_build_object('transfer_id',t.id,'state',t.state);
  else
   if t.current_payer_binding_id is not null or not app_private.payment_verified_account((p_input->>'payer_account_id')::uuid) then raise exception 'STATE_CONFLICT';end if;
   file:=app_private.payment_assert_file((p_input->>'evidence_file_id')::uuid,'payer_ownership','transfer',t.id);
   insert into finance_private.transfer_payer_bindings(transfer_id,payer_account_id,evidence_file_id,verified_by,reason,command_id) values(t.id,(p_input->>'payer_account_id')::uuid,file.id,actor,p_input->>'reason',(context->>'command_id')::uuid) returning id into binding;
   update finance_private.incoming_transfers set current_payer_binding_id=binding,version=incoming_transfers.version+1,updated_at=now() where id=t.id returning * into t;
   perform finance_private.finance_ensure_owned_credit(t.id,context);result:=jsonb_build_object('payer_binding_id',binding,'transfer_id',t.id);
  end if;resource:=t.id;version:=t.version;
 elsif p_name in('submit_receipt','replace_receipt') then
  if p_name='replace_receipt' then
   select * into review from app_private.review_cases where receipt_id=r.id for update;
   select * into r from app_private.receipts where id=r.id for update;if expected is distinct from r.version then raise exception 'VERSION_CONFLICT';end if;
   select * into e from app_private.receipt_evidence where id=r.current_evidence_id;select * into c from finance_private.charges where id=r.charge_id;
  else
   if (p_input->>'enrollment_id')::uuid is distinct from c.enrollment_id or p_input->>'currency' is distinct from c.currency then raise exception 'VALIDATION_ERROR';end if;
   select * into account_version from finance_private.receiving_account_versions where id=(p_input->>'receiving_account_version_id')::uuid;select * into account from finance_private.receiving_accounts where id=account_version.receiving_account_id;
   if account_version.id is null or account_version.approved_at is null or not account.enabled or account.current_version_id<>account_version.id then raise exception 'DESTINATION_UNVERIFIED';end if;
   if p_input->>'channel' is distinct from account.channel or p_input->>'reference' is null or length(btrim(p_input->>'reference')) not between 1 and 200 then raise exception 'VALIDATION_ERROR';end if;
   amount:=app_private.package_safe_integer(p_input->'transferred_amount_minor',1);at_time:=(p_input->>'transferred_at')::timestamptz;
   if at_time is not null and(not isfinite(at_time) or at_time<timestamptz '0001-01-01 00:00:00+00' or at_time>=timestamptz '10000-01-01 00:00:00+00') then raise exception 'INVALID_TIME';end if;
  end if;
  file:=app_private.payment_assert_file((p_input->>'file_id')::uuid,'payment_receipt','charge',c.id,actor);
  if file.learner_id is distinct from c.learner_id or file.charge_id is distinct from c.id then raise exception 'EVIDENCE_REQUIRED';end if;
  if p_name='submit_receipt' then insert into app_private.receipts(learner_id,charge_id,enrollment_id,submitted_by) values(c.learner_id,c.id,c.enrollment_id,actor) returning * into r;
  else
   update app_private.receipt_evidence set state='superseded' where id=e.id;
   update app_private.payment_allocation_plans set state='superseded' where receipt_id=r.id and state='active';
   account_version.id:=e.receiving_account_version_id;account.channel:=e.channel;amount:=e.reported_amount_minor;at_time:=e.transferred_at;
   update app_private.receipts set current_evidence_version=current_evidence_version+1,version=receipts.version+1,updated_at=now() where id=r.id returning * into r;
  end if;
  insert into app_private.receipt_evidence(receipt_id,evidence_version,learner_id,charge_id,enrollment_id,uploader_account_id,submission_authority,file_id,checksum_sha256,receiving_account_version_id,channel,reported_amount_minor,currency,reference,transferred_at,state)
  values(r.id,r.current_evidence_version,c.learner_id,c.id,c.enrollment_id,actor,jsonb_build_object('actor_account_id',actor,'learner_id',c.learner_id,'scope','payments','checked_at',now()),file.id,file.checksum_sha256,account_version.id,account.channel,amount,c.currency,case when p_name='replace_receipt' then e.reference else btrim(p_input->>'reference') end,at_time,'ready_for_review') returning id into entry;
  update app_private.receipts set current_evidence_id=entry where id=r.id;
  if p_name='submit_receipt' then insert into app_private.review_cases(receipt_id,current_evidence_version) values(r.id,r.current_evidence_version) returning * into review;
  else update app_private.review_cases set current_evidence_version=r.current_evidence_version,state='unassigned',owner_id=null,claim_expires_at=null,resolved_at=null,version=review_cases.version+1,updated_at=now() where id=review.id returning * into review;end if;
  insert into app_private.review_case_events(case_id,event_type,evidence_version,actor_account_id,command_id,reason) values(review.id,p_name,r.current_evidence_version,actor,(context->>'command_id')::uuid,p_input->>'reason');
  resource:=r.id;version:=r.version;result:=case when p_name='submit_receipt' then jsonb_build_object('receipt_id',r.id,'case_id',review.id,'evidence_state','ready_for_review') else jsonb_build_object('new_evidence_version',r.current_evidence_version,'case_id',review.id) end;
  if p_name='submit_receipt' then perform set_config('response.status','201',true);end if;
 else
  select * into review from app_private.review_cases where id=(p_input->>'case_id')::uuid for update;if review.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;if expected is distinct from review.version then raise exception 'VERSION_CONFLICT';end if;
  if review.state='resolved' then raise exception 'STATE_CONFLICT';end if;
  owner:=review.owner_id;state:=review.state;
  if p_name='claim_review_case' then if owner is not null and review.claim_expires_at>now() and owner<>actor then raise exception 'OWNER_REQUIRED';end if;owner:=actor;state:='claimed';
  elsif p_name='assign_review_case' then owner:=(p_input->>'owner_id')::uuid;perform app_private.payment_current_staff(owner);if not app_private.payment_verified_account(owner) then raise exception 'FORBIDDEN';end if;state:='claimed';
  elsif p_name='release_review_case' then if owner is distinct from actor and not app_private.has_role(actor,'admin') then raise exception 'OWNER_REQUIRED';end if;owner:=null;state:='unassigned';
  elsif p_name='renew_review_claim' then if owner is distinct from actor or review.claim_expires_at<=now() or review.state<>'claimed' then raise exception 'OWNER_REQUIRED';end if;
  elsif p_name='decide_review_case' then
   if owner is distinct from actor or review.claim_expires_at<=now() or review.state<>'claimed' then raise exception 'OWNER_REQUIRED';end if;
   if p_input->>'decision' is null or p_input->>'decision' not in('needs_information','escalated','resolved_rejected') then raise exception 'VALIDATION_ERROR';end if;
   state:=case when p_input->>'decision'='resolved_rejected' then 'resolved' else p_input->>'decision' end;
   if state='resolved' then update app_private.receipt_evidence set state='rejected' where receipt_id=review.receipt_id and evidence_version=review.current_evidence_version;end if;
  else raise exception 'VALIDATION_ERROR';end if;
  update app_private.review_cases set owner_id=owner,state=payment_source_command.state,claim_expires_at=case when payment_source_command.state='claimed' then now()+interval '15 minutes' else null end,resolved_at=case when payment_source_command.state='resolved' then now() else null end,version=review_cases.version+1,updated_at=now() where id=review.id returning * into review;
  insert into app_private.review_case_events(case_id,event_type,evidence_version,owner_id,actor_account_id,command_id,reason) values(review.id,p_name,review.current_evidence_version,review.owner_id,actor,(context->>'command_id')::uuid,p_input->>'reason');
  resource:=review.id;version:=review.version;result:=jsonb_build_object('state',review.state);
  if p_name in('claim_review_case','assign_review_case') then result:=result||jsonb_build_object('owner_id',review.owner_id,'claim_expires_at',review.claim_expires_at);elsif p_name='renew_review_claim' then result:=result||jsonb_build_object('claim_expires_at',review.claim_expires_at);end if;
 end if;
 return app_private.booking_finish(context,resource,version,result,'payment_'||p_name,jsonb_build_object('resource_id',resource));
exception when unique_violation then if p_name='record_manual_transfer' then raise exception 'DUPLICATE_TRANSFER';else raise exception 'STATE_CONFLICT';end if;when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then raise exception 'VALIDATION_ERROR';end $$;
create function finance_private.finance_credit_available(p_lot_id uuid) returns bigint language sql stable security definer set search_path='' as $$
 select (l.original_minor-coalesce((select sum(r.amount_minor) from finance_private.credit_reservations r where r.credit_lot_id=l.id and r.state in('reserved','consumed')),0))::bigint from finance_private.customer_credit_lots l where l.id=p_lot_id
$$;
create function finance_private.finance_transfer_balance(p_transfer_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare t finance_private.incoming_transfers%rowtype;s finance_private.transfer_settlements%rowtype;b finance_private.transfer_payer_bindings%rowtype;gross numeric;reversed numeric;allocated numeric;reserved numeric;converted numeric;unapplied numeric;available numeric;exposure numeric;review boolean;begin
 select * into t from finance_private.incoming_transfers where id=p_transfer_id;if t.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 select * into s from finance_private.transfer_settlements where transfer_id=t.id;select * into b from finance_private.transfer_payer_bindings where id=t.current_payer_binding_id;
 gross:=coalesce(s.amount_minor,0);select coalesce(sum(amount_minor),0) into reversed from finance_private.transfer_reversals where transfer_id=t.id;
 select coalesce(sum(a.amount_minor-coalesce((select sum(r.amount_minor) from finance_private.allocation_reversals r where r.allocation_id=a.id),0)),0) into allocated from finance_private.payment_allocations a where a.transfer_id=t.id;
 select coalesce(sum(r.amount_minor) filter(where r.state='reserved'),0),coalesce(sum(r.amount_minor) filter(where r.state='consumed' and r.purpose='package_grant'),0) into reserved,converted from finance_private.credit_reservations r join finance_private.customer_credit_lots l on l.id=r.credit_lot_id where l.transfer_id=t.id;
 unapplied:=gross-reversed-allocated-converted;exposure:=greatest(0,-unapplied);
 review:=exposure>0 or exists(select 1 from app_private.reconciliation_exceptions e where e.source_type='transfer' and e.source_id=t.id and e.state='open');
 available:=case when review then 0 else greatest(0,unapplied-reserved) end;
 if greatest(abs(gross),abs(reversed),abs(allocated),abs(reserved),abs(converted),abs(unapplied),abs(available),abs(exposure))>9007199254740991 then raise exception 'AMOUNT_OUT_OF_RANGE';end if;
 -- Refund outgoing/return primary rows extend this projection before those commands are enabled.
 return jsonb_build_object('transfer_id',t.id,'version',t.version,'state',t.state,'currency',t.currency,'gross_settled_minor',gross,'reversed_minor',reversed,'net_allocated_minor',allocated,'refund_settled_minor',0,'refund_returned_minor',0,'credit_converted_minor',converted,'refund_reserved_minor',coalesce((select sum(r.amount_minor) from finance_private.credit_reservations r join finance_private.customer_credit_lots l on l.id=r.credit_lot_id where l.transfer_id=t.id and r.purpose='refund' and r.state='reserved'),0),'unapplied_signed_minor',unapplied,'available_minor',available,'recovery_exposure_minor',exposure,'payer_binding_id',b.id,'payer_account_id',b.payer_account_id,'reconciliation_state',case when review then 'requires_review' else 'clear' end);
end $$;
create function finance_private.finance_ensure_owned_credit(p_transfer_id uuid,p_context jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare t finance_private.incoming_transfers%rowtype;s finance_private.transfer_settlements%rowtype;b finance_private.transfer_payer_bindings%rowtype;result uuid;begin
 select * into t from finance_private.incoming_transfers where id=p_transfer_id for update;select * into s from finance_private.transfer_settlements where transfer_id=t.id;select * into b from finance_private.transfer_payer_bindings where id=t.current_payer_binding_id;
 if s.id is null or b.id is null then return null;end if;
 select id into result from finance_private.customer_credit_lots where transfer_id=t.id and origin_kind='settlement';if result is not null then return result;end if;
 insert into finance_private.customer_credit_lots(transfer_id,payer_binding_id,payer_account_id,origin_kind,original_minor,currency,command_id,source_line_key) values(t.id,b.id,b.payer_account_id,'settlement',s.amount_minor,s.currency,(p_context->>'command_id')::uuid,'settlement-credit:'||t.id) returning id into result;
 insert into finance_private.credit_lot_accounts(credit_lot_id) values(result);return result;
end $$;
create function finance_private.finance_post_settlement(p_transfer_id uuid,p_verified_statement_id uuid,p_context jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare t finance_private.incoming_transfers%rowtype;result uuid;begin
 select * into t from finance_private.incoming_transfers where id=p_transfer_id for update;if t.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 select ledger_transaction_id into result from finance_private.transfer_settlements where transfer_id=t.id;if result is not null then return result;end if;
 perform app_private.payment_assert_file(p_verified_statement_id,'statement','receiving_account',t.receiving_account_id);
 return finance_private.finance_post_balanced('transfer-settled:'||t.id,'transfer_settled',t.id,t.currency,(p_context->>'effective_at')::timestamptz,jsonb_build_array(
  jsonb_build_object('account_code','channel_cash','transfer_id',t.id,'receiving_account_id',t.receiving_account_id,'signed_minor',t.amount_minor),
  jsonb_build_object('account_code','unapplied_customer_funds','transfer_id',t.id,'receiving_account_id',t.receiving_account_id,'signed_minor',-t.amount_minor)),p_context);
end $$;

create function app_private.payment_payer_dto(p_account_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('account_id',a.id,'display_name',coalesce(p.display_name,'Account'),'masked_contact',coalesce((select case when c.channel='email' then left(c.destination,1)||'***@'||split_part(c.destination,'@',2) else '***'||right(c.destination,4) end from app_private.verified_contacts c where c.account_id=a.id and c.revoked_at is null and c.verified_at is not null order by c.verified_at desc,c.id limit 1),'Not available')) from app_private.accounts a join app_private.people p on p.id=a.person_id where a.id=p_account_id
$$;
create function app_private.payment_transfer_dto(p_transfer_id uuid,p_actor uuid,p_staff boolean default false) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare t finance_private.incoming_transfers%rowtype;b jsonb;result jsonb;begin
 select * into t from finance_private.incoming_transfers where id=p_transfer_id;if t.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;b:=finance_private.finance_transfer_balance(t.id);
 result:=jsonb_build_object('transfer_id',t.id,'version',t.version,'channel',t.channel,'amount_minor',t.amount_minor,'currency',t.currency,'state',t.state,'settled_at',(select settled_at from finance_private.transfer_settlements where transfer_id=t.id),'reversed_minor',b->'reversed_minor','available_minor',b->'available_minor','refund_reserved_minor',b->'refund_reserved_minor','recovery_exposure_minor',b->'recovery_exposure_minor','reconciliation_state',b->>'reconciliation_state','payer_is_current_account',coalesce((b->>'payer_account_id')::uuid=p_actor,false));
 if p_staff then result:=result||jsonb_build_object('receiving_account_id',t.receiving_account_id,'receiving_account_version_id',t.receiving_account_version_id,'external_id',t.external_id,'observed_at',t.observed_at,'payer',app_private.payment_payer_dto((b->>'payer_account_id')::uuid));end if;return result;
end $$;
create function app_private.payment_receiving_dto(p_account_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('receiving_account_id',a.id,'version',a.version,'channel',a.channel,'enabled',a.enabled,'current_version_id',a.current_version_id,'latest_version',jsonb_build_object('receiving_account_version_id',v.id,'instructions_version',v.instructions_version,'collection_identifier',v.collection_identifier,'display_instructions',v.display_instructions,'approved_at',v.approved_at)) from finance_private.receiving_accounts a join lateral(select * from finance_private.receiving_account_versions where receiving_account_id=a.id order by version_number desc limit 1)v on true where a.id=p_account_id
$$;
create function api.list_receiving_accounts(p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;begin
 perform app_private.payment_current_staff(actor);if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_receiving_dto(x.id)) order by x.created_at desc,x.id desc),'[]') into rows from(select a.* from finance_private.receiving_accounts a where(app_private.has_role(actor,'admin') or(a.enabled and a.current_version_id is not null)) and(p_cursor is null or(a.created_at,a.id)<(after_at,after_id)) order by a.created_at desc,a.id desc limit p_limit+1)x;
 return app_private.package_page(rows,p_limit);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then raise exception 'VALIDATION_ERROR';end $$;
create function api.get_incoming_transfer(p_transfer_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();begin perform app_private.payment_current_staff(actor);return app_private.payment_transfer_dto(p_transfer_id,actor,true);end $$;
create function api.get_my_transfer(p_transfer_id uuid,p_refund_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();b jsonb;begin
 if p_limit is null or p_limit not between 1 and 100 or(p_refund_cursor is not null and length(p_refund_cursor)>200) then raise exception 'VALIDATION_ERROR';end if;
 b:=finance_private.finance_transfer_balance(p_transfer_id);if (b->>'payer_account_id')::uuid is distinct from actor then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 return jsonb_build_object('view','payer_only','transfer',app_private.payment_transfer_dto(p_transfer_id,actor,false),'credit',jsonb_build_object('source_type','unapplied_credit','source_id',p_transfer_id,'available_minor',b->'available_minor','refund_reserved_minor',b->'refund_reserved_minor','refundable_minor',b->'available_minor'),'refund_page',jsonb_build_object('items','[]'::jsonb,'next_cursor',null));
end $$;

create function api.create_receiving_account(p_channel text,p_collection_identifier text,p_display_instructions text,p_ownership_evidence_file_id uuid,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.payment_source_command('create_receiving_account',jsonb_build_object('channel',p_channel,'collection_identifier',p_collection_identifier,'display_instructions',p_display_instructions,'ownership_evidence_file_id',p_ownership_evidence_file_id),p_idempotency_key) $$;
create function api.approve_receiving_account(p_receiving_account_id uuid,p_enabled boolean,p_verification_note text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.payment_source_command('approve_receiving_account',jsonb_build_object('receiving_account_id',p_receiving_account_id,'enabled',p_enabled,'verification_note',p_verification_note,'expected_version',p_expected_version),p_idempotency_key) $$;
create function api.record_manual_transfer(p_receiving_account_id uuid,p_channel text,p_external_id text,p_amount_minor bigint,p_currency text,p_observed_at timestamptz,p_statement_evidence_file_id uuid,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.payment_source_command('record_manual_transfer',jsonb_build_object('receiving_account_id',p_receiving_account_id,'channel',p_channel,'external_id',p_external_id,'amount_minor',p_amount_minor,'currency',p_currency,'observed_at',p_observed_at,'statement_evidence_file_id',p_statement_evidence_file_id),p_idempotency_key) $$;
create function api.verify_transfer_settlement(p_transfer_id uuid,p_statement_evidence_id uuid,p_external_id text,p_settled_at timestamptz,p_amount_minor bigint,p_currency text,p_verification_note text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.payment_source_command('verify_transfer_settlement',jsonb_build_object('transfer_id',p_transfer_id,'statement_evidence_id',p_statement_evidence_id,'external_id',p_external_id,'settled_at',p_settled_at,'amount_minor',p_amount_minor,'currency',p_currency,'verification_note',p_verification_note,'expected_version',p_expected_version),p_idempotency_key) $$;
