create function api.submit_receipt(p_enrollment_id uuid,p_charge_id uuid,p_file_id uuid,p_receiving_account_version_id uuid,p_channel text,p_transferred_amount_minor bigint,p_currency text,p_reference text,p_transferred_at timestamptz,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.payment_source_command('submit_receipt',jsonb_build_object('enrollment_id',p_enrollment_id,'charge_id',p_charge_id,'file_id',p_file_id,'receiving_account_version_id',p_receiving_account_version_id,'channel',p_channel,'transferred_amount_minor',p_transferred_amount_minor,'currency',p_currency,'reference',p_reference,'transferred_at',p_transferred_at),p_idempotency_key) $$;
