create function app_private.payment_source_immutable() returns trigger language plpgsql set search_path='' as $$
declare allowed text[];begin
 if tg_op='DELETE' then raise exception 'IMMUTABLE_VERSION';end if;
 allowed:=case tg_table_name
 when 'receiving_accounts' then array['current_version_id','enabled','version','updated_at']
 when 'receiving_account_versions' then array['approved_by','approved_at']
 when 'incoming_transfers' then array['state','current_payer_binding_id','version','updated_at']
 when 'receipts' then array['current_evidence_version','current_evidence_id','version','updated_at']
 when 'receipt_evidence' then array['state']
 when 'review_cases' then array['current_evidence_version','state','owner_id','claim_expires_at','resolved_at','version','updated_at']
 when 'payment_allocation_plans' then array['state']
 when 'transfer_payment_plan_links' then array['state','version','updated_at']
 when 'credit_lot_accounts' then array['version','updated_at']
 when 'credit_reservations' then array['state','version','updated_at']
 when 'reconciliation_exceptions' then array['owner_id','state','signed_exposure_minor','resolution_id','version','updated_at']
 when 'credit_conversion_intents' then array['state','consumed_grant_id','version','updated_at'] else '{}'::text[] end;
 if(to_jsonb(old)-allowed) is distinct from(to_jsonb(new)-allowed) then raise exception 'IMMUTABLE_VERSION';end if;
 if tg_table_name='receiving_account_versions' and to_jsonb(old)->>'approved_at' is not null and(to_jsonb(old)->'approved_at' is distinct from to_jsonb(new)->'approved_at' or to_jsonb(old)->'approved_by' is distinct from to_jsonb(new)->'approved_by') then raise exception 'IMMUTABLE_VERSION';end if;
 return new;
end $$;
do $$ declare name text;schema_name text;f record;begin
 foreach schema_name in array array['app_private','finance_private'] loop
  foreach name in array case when schema_name='app_private' then array['files','receipts','receipt_evidence','review_cases','review_case_events','payment_allocation_plans','payment_plan_targets','transfer_payment_plan_links','transfer_payment_plan_acceptances','reconciliation_exceptions','credit_conversion_intents'] else array['receiving_accounts','receiving_account_versions','incoming_transfers','transfer_settlements','transfer_payer_bindings','payment_allocations','allocation_reversals','customer_credit_lots','credit_lot_accounts','credit_reservations','credit_applications','transfer_reversals','transfer_reversal_resolutions'] end loop
   execute format('alter table %I.%I enable row level security',schema_name,name);execute format('create policy commands_access on %I.%I to git_tutor_commands using(true) with check(true)',schema_name,name);
   execute format('grant select,insert on %I.%I to git_tutor_commands',schema_name,name);execute format('revoke all on %I.%I from public,anon,authenticated,service_role,git_tutor_worker',schema_name,name);
   execute format('create trigger immutable_source before update or delete on %I.%I for each row execute function app_private.payment_source_immutable()',schema_name,name);
  end loop;
 end loop;
 grant update on finance_private.receiving_accounts,finance_private.receiving_account_versions,finance_private.incoming_transfers,finance_private.credit_lot_accounts,finance_private.credit_reservations,app_private.receipts,app_private.receipt_evidence,app_private.review_cases,app_private.payment_allocation_plans,app_private.transfer_payment_plan_links,app_private.reconciliation_exceptions,app_private.credit_conversion_intents to git_tutor_commands;
 for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname in('payment_current_staff','payment_source_command','payment_verified_account','payment_assert_file','payment_payer_dto','payment_transfer_dto','payment_receiving_dto','payment_source_immutable')) or(n.nspname='finance_private' and p.proname in('finance_credit_available','finance_transfer_balance','finance_ensure_owned_credit','finance_post_settlement')) or(n.nspname='api' and p.proname in('list_receiving_accounts','get_incoming_transfer','get_my_transfer','create_receiving_account','approve_receiving_account','record_manual_transfer','verify_transfer_settlement','bind_transfer_payer','submit_receipt','replace_receipt','claim_review_case','renew_review_claim','release_review_case','assign_review_case','decide_review_case')) loop
  execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
